import{_ as r,o as a,c as o,an as t}from"./chunks/framework.B-kTVkRm.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/faq.md","filePath":"getting-started/faq.md","lastUpdated":null}'),c={name:"getting-started/faq.md"};function s(n,e,i,l,d,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ {#faq}&quot;">​</a></h1><h2 id="Why-is-there-no-renewal-or-AR-constructor?" tabindex="-1">Why is there no renewal or AR constructor? <a class="header-anchor" href="#Why-is-there-no-renewal-or-AR-constructor?" aria-label="Permalink to &quot;Why is there no renewal or AR constructor? {#Why-is-there-no-renewal-or-AR-constructor?}&quot;">​</a></h2><p>The operators describe steps, not models. A renewal process is <a href="/previews/PR340/lib/public#ComposableRecurrences.Recurrence"><code>Recurrence(gi)</code></a> with the reproduction number as its gain, and an AR(p) process is <code>Recurrence(ρ)</code> with the innovations as <code>add</code>. Modelling packages such as <a href="https://composableturingidmodels.epiaware.org" target="_blank" rel="noreferrer">ComposableTuringIDModels.jl</a> name these and give them priors.</p><h2 id="Recurrence-clashes-with-Lux" tabindex="-1"><code>Recurrence</code> clashes with Lux <a class="header-anchor" href="#Recurrence-clashes-with-Lux" aria-label="Permalink to &quot;`Recurrence` clashes with Lux {#Recurrence-clashes-with-Lux}&quot;">​</a></h2><p>Lux also exports a <code>Recurrence</code>. With both loaded by <code>using</code>, write <a href="/previews/PR340/lib/public#ComposableRecurrences.Recurrence"><code>ComposableRecurrences.Recurrence</code></a> or import the one you need by name.</p>',5)])])}const m=r(c,[["render",s]]);export{p as __pageData,m as default};
